def transform(grid):
    g=[row[:] for row in grid]
    # Recover the missing rectangle from the vertically mirrored position.
    zeros=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==0]
    if not zeros:
        return g
    r0=min(r for r,c in zeros); r1=max(r for r,c in zeros)
    c0=min(c for r,c in zeros); c1=max(c for r,c in zeros)
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            g[r][c]=grid[len(grid)-1-r][c]
    return [row[c0:c1+1] for row in g[r0:r1+1]]
